# Adaptive rejection sampling (Gilks and Wild, 1992).
# The supplied density is an ordinary (not log) density and must accept a
# vector x and return one value per x.  It need not be normalized.

sample_count <- 1000L

.ars_density <- function(density_function, x, env = parent.frame()) {
  value <- if (is.function(density_function)) {
    density_function(x)
  } else if (is.expression(density_function) || is.language(density_function)) {
    eval(density_function, envir = list(x = x), enclos = env)
  } else stop("density_function must be a function or an expression")
  if (length(value) != length(x))
    stop("density_function must be vectorized and return one value per x")
  value <- as.numeric(value)
  if (any(is.nan(value)) || any(value < 0, na.rm = TRUE) || any(!is.finite(value) & value != Inf))
    stop("density_function returned invalid (negative, NaN, or infinite) values")
  if (any(is.infinite(value) & value > 0)) stop("density_function returned +Inf")
  value
}

.ars_logdensity <- function(f, x, env) {
  y <- .ars_density(f, x, env)
  out <- rep(-Inf, length(y)); ok <- y > 0
  out[ok] <- log(y[ok]); out
}

.ars_check_concavity <- function(x, h, tolerance = 1e-8) {
  s <- diff(h) / diff(x)
  good <- is.finite(s) & (s[-length(s)] + tolerance >= s[-1])
  if (!all(good)) stop("density is not log-concave on the supplied domain (secant slopes increase)")
  invisible(TRUE)
}

# Find intersections of adjacent tangent lines and the normalized masses of
# the piecewise-exponential upper hull.
.ars_hull <- function(x, h) {
  m <- diff(h) / diff(x)
  if (any(!is.finite(m))) stop("cannot construct envelope: density is zero at an initial point")
  z <- numeric(length(x) + 1L); z[1] <- -Inf; z[length(z)] <- Inf
  for (i in seq_len(length(x) - 1L)) {
    den <- m[i] - m[i + 1L]
    if (abs(den) < 1e-12) z[i + 1L] <- (x[i] + x[i + 1L]) / 2
    else z[i + 1L] <- (h[i + 1L] - m[i + 1L] * x[i + 1L] - h[i] + m[i] * x[i]) / den
  }
  if (any(!is.finite(z[2:(length(z)-1L)])) || any(diff(z) <= 0))
    stop("failed to construct a valid ARS envelope; density may not be log-concave")
  # Segment i is tangent i, truncated to z[i]:z[i+1].  Work on a
  # log scale, since normal tails routinely underflow on the original scale.
  logmass <- numeric(length(x))
  for (i in seq_along(x)) {
    a <- z[i]; b <- z[i + 1L]; slope <- m[i]; intercept <- h[i] - slope*x[i]
    if (slope == 0) logmass[i] <- intercept + log(b-a)
    else {
      ea <- if (is.infinite(a)) -Inf else intercept + slope*a
      eb <- if (is.infinite(b)) -Inf else intercept + slope*b
      if (slope > 0 && is.infinite(b)) stop("right tail is not integrable")
      if (slope < 0 && is.infinite(a)) stop("left tail is not integrable")
      top <- max(ea, eb)
      logmass[i] <- top + log(exp(ea-top) - exp(eb-top)) - log(abs(slope))
    }
  }
  if (any(!is.finite(logmass) & logmass != -Inf)) stop("invalid envelope mass")
  list(slopes=m, intercept=h-m*x, bounds=z, logmass=logmass)
}

.ars_initial_points <- function(domain) {
  lo <- domain[1]; hi <- domain[2]
  if (is.finite(lo) && is.finite(hi)) return(seq(lo, hi, length.out=7L)[c(2,4,6)])
  if (is.finite(lo)) return(lo + c(.25, 1, 3, 7))
  if (is.finite(hi)) return(hi - c(7, 3, 1, .25))
  c(-3, -1, 0, 1, 3)
}

.ars_draw_envelope <- function(hull) {
  lm <- hull$logmass; mx <- max(lm); p <- exp(lm-mx); p <- p/sum(p)
  i <- sample.int(length(p), 1L, prob=p)
  a <- hull$bounds[i]; b <- hull$bounds[i+1L]; s <- hull$slopes[i]
  u <- runif(1)
  if (s == 0) x <- a + u*(b-a)
  else {
    ea <- if (is.infinite(a)) 0 else exp(s*a)
    eb <- if (is.infinite(b)) 0 else exp(s*b)
    # inverse of exp(s*x) truncated to [a,b], avoiding infinite products
    x <- log(ea + u*(eb-ea))/s
  }
  list(x=x, log_upper=hull$intercept[i] + s*x)
}

ars <- function(density_function, domain, n = sample_count) {
  if (!(is.function(density_function) || is.expression(density_function) || is.language(density_function)))
    stop("density_function must be a function or expression")
  if (length(domain) != 2L || any(is.na(domain)) || domain[1] >= domain[2] ||
      any(domain != domain) || domain[1] == Inf || domain[2] == -Inf)
    stop("domain must be an increasing two-element numeric interval")
  if (!is.numeric(domain)) stop("domain must be numeric")
  if (length(n) != 1L || !is.numeric(n) || !is.finite(n) || n < 0 || n != as.integer(n))
    stop("n must be one non-negative integer")
  n <- as.integer(n); if (n == 0L) return(numeric(0))
  env <- parent.frame(); x <- sort(unique(.ars_initial_points(domain)))
  x <- x[x > domain[1] & x < domain[2]]
  h <- .ars_logdensity(density_function, x, env)
  if (all(!is.finite(h))) stop("density is zero throughout the initial support")
  .ars_check_concavity(x, h)
  out <- numeric(n); accepted <- 0L; attempts <- 0L
  while (accepted < n) {
    attempts <- attempts + 1L
    if (attempts > max(10000L, 1000L*n)) stop("sampling stalled; check support and log-concavity")
    hull <- .ars_hull(x, h); d <- .ars_draw_envelope(hull); xx <- d$x
    if (xx <= domain[1] || xx >= domain[2]) next
    hh <- .ars_logdensity(density_function, xx, env)
    # This is both the ARS squeeze rejection test and an online diagnostic:
    # a log-concave target cannot exceed its tangent upper hull.
    if (is.finite(hh) && hh > d$log_upper + 1e-7)
      stop("density failed the log-concavity check during sampling")
    if (is.finite(hh) && log(runif(1)) <= hh - d$log_upper) {
      accepted <- accepted + 1L; out[accepted] <- xx
    } else if (is.finite(hh)) {
      x <- sort(c(x, xx)); h <- sort(c(h, hh))
      .ars_check_concavity(x, h)
    }
  }
  out
}

# Formal stochastic tests against exact moments and validation behaviour.
test <- function() {
  cat("Adaptive rejection sampler tests (seed = 2024)\n"); set.seed(2024)
  z <- ars(function(x) dnorm(x), c(-Inf, Inf), 4000)
  mz <- mean(z); sz <- sd(z); pass <- abs(mz) < .10 && abs(sz-1) < .10
  cat(sprintf("NORMAL_MOMENTS: %s (mean=%.4f, sd=%.4f)\n", ifelse(pass,"PASS","FAIL"), mz, sz))
  write.table(z, "/app/normal_samples.txt", row.names=FALSE, col.names=FALSE)
  e <- ars(function(x) dexp(x), c(0, Inf), 4000)
  me <- mean(e); se <- sd(e); pass <- abs(me-1) < .08 && abs(se-1) < .08
  cat(sprintf("EXPONENTIAL_MOMENTS: %s (mean=%.4f, sd=%.4f)\n", ifelse(pass,"PASS","FAIL"), me, se))
  invalid <- inherits(try(ars(function(x) dnorm(x), c(1,1), 2), silent=TRUE), "try-error")
  nonconcave <- inherits(try(ars(function(x) exp(-x^2/2)*(1+.8*cos(3*x)), c(-4,4), 5), silent=TRUE), "try-error")
  cat(sprintf("INPUT_VALIDATION: %s\n", ifelse(invalid,"PASS","FAIL")))
  cat(sprintf("NON_LOG_CONCAVE_REJECTION: %s\n", ifelse(nonconcave,"PASS","FAIL")))
  invisible(all(pass, invalid, nonconcave))
}

if (sys.nframe() == 0L) test()

