# Estimate the derivative of log density locally.  ARS only needs these
# slopes; numerical differentiation keeps the public interface density-only.
eps <- 1e-5 * pmax(1, abs(x))
m <- numeric(length(x))
for (j in seq_along(x)) {
  left <- if (j == 1L) x[j] else x[j] - eps[j]
  right <- if (j == length(x)) x[j] else x[j] + eps[j]
  if (j == 1L) m[j] <- (h[j+1L] - h[j]) / (x[j+1L] - x[j])
  else if (j == length(x)) m[j] <- (h[j] - h[j-1L]) / (x[j] - x[j-1L])
  else {
    hv <- .ars_logdensity(get("density_function", .GlobalEnv), c(left, right), .GlobalEnv)
    m[j] <- diff(hv) / (right-left)
  }
}

